#!/bin/bash -eu
# Generated by fuzzbench_generate.py for bug transplant evaluation

cd /src/ghostpdl

# Checkout target commit
git checkout 2be8b436910cfc8b013a13df000c3c854cf3c5c5

# Restore harness sources that live outside the project git repository.
if [ -f /src/patches/harness_sources/manifest.json ]; then
    python3 - <<'PY'
import json
import shutil
from pathlib import Path

root = Path("/src/patches/harness_sources")
for entry in json.loads((root / "manifest.json").read_text()):
    source = root / entry["snapshot"]
    destination = Path(entry["container_path"])
    destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(source, destination)
PY
fi

# Apply dispatch harness first (modifies build system), then bug patches
if ! git apply --check /src/patches/harness.diff 2>/dev/null; then
    echo "Trying git apply --3way for harness.diff..."
    git apply --3way /src/patches/harness.diff
else
    git apply /src/patches/harness.diff
fi

if ! git apply --check /src/patches/combined.diff 2>/dev/null; then
    echo "Trying git apply --3way for combined.diff..."
    git apply --3way /src/patches/combined.diff
else
    git apply /src/patches/combined.diff
fi

# --- Fix library CMakeLists.txt for new source files from combined.diff ---
# combined.diff may create new .c files (e.g., zfp_getcell.c) that need to
# be added to the library's explicit source list.
if [ -d blosc ] && [ -f blosc/CMakeLists.txt ]; then
    for newfile in blosc/*.c; do
        base=$(basename "$newfile")
        if ! grep -q "$base" blosc/CMakeLists.txt 2>/dev/null; then
            echo "Adding $base to blosc/CMakeLists.txt"
            sed -i "/^set(SOURCES /s/)/ $base)/" blosc/CMakeLists.txt
        fi
    done
fi

# --- Original build commands ---
pushd $SRC/cups
# Fix bad line
sed -i '2110s/\(\s\)f->value/\1(int)f->value/' cups/ppd-cache.c

# Keep this flag live for the whole build: libafl's clang-17 elevates
# implicit-function-declaration to an error (e.g. gx_dc_is_pattern2_color
# in base/gxstroke.c), which the older clang-15 the other fuzzers ship
# still treats as a warning.
export CFLAGS="${CFLAGS:-} -Wno-error=implicit-function-declaration"
export CXXFLAGS="${CXXFLAGS:-} -Wno-error=implicit-function-declaration"

# ghostpdl fires UBSAN "left shift of negative value" in base/std.h:66,
# base/gxpath.c, base/gspath.c, base/gxcpath.c, psi/imainarg.c and
# "member access within null pointer" in base/gsalloc.c on every input.
# afl++ forces ASAN_OPTIONS=abort_on_error=1 when spawning the target,
# overriding our Dockerfile ENV, so every UBSAN report turns into
# SIGABRT and afl++ rejects all 1147 seeds with "We need at least one
# valid input seed that does not crash!". Strip the specific UBSAN
# instrumentation for those pre-existing patterns — ASAN heap/stack/UAF
# detection for the transplanted bugs is unaffected.
export CFLAGS="${CFLAGS} -fno-sanitize=shift,null"
export CXXFLAGS="${CXXFLAGS} -fno-sanitize=shift,null"

LSB_BUILD=y ./configure --prefix="$WORK" --libdir="$OUT" --disable-gnutls \
   --disable-libusb --with-components=core

make clean
make install-headers install-libs
make -C filter libs install-libs
install -m755 cups-config "$WORK"/cups-config
popd

rm -rf cups/libs || true
rm -rf freetype || true
rm -rf zlib || true
rm -rf libpng || true

if [ -d "$SRC/freetype" ]; then
    mv "$SRC/freetype" freetype
fi

CUPSCONFIG="$WORK/cups-config"
CUPS_CFLAGS=$($CUPSCONFIG --cflags)
CUPS_LDFLAGS=$($CUPSCONFIG --ldflags)
CUPS_LIBS=$($CUPSCONFIG --image --libs)
export CXXFLAGS="$CXXFLAGS $CUPS_CFLAGS"

# --disable-fontconfig: FuzzBench runner images are slim and do not ship
# libfontconfig.so.1, which would make the fuzzer fail to start. Font
# discovery isn't needed for the transplanted bug crashes.
CPPFLAGS="${CPPFLAGS:-} $CUPS_CFLAGS -DPACIFY_VALGRIND" ./autogen.sh \
  CUPSCONFIG=$CUPSCONFIG \
  --enable-freetype --disable-fontconfig \
  --enable-cups --with-ijs --with-jbig2dec \
  --with-drivers=cups,ljet4,laserjet,pxlmono,pxlcolor,pcl3,uniprint

# ghostpdl's autogen.sh auto-adds `-fno-sanitize-recover=...,shift,signed-integer-overflow,...`
# when UBSAN is detected. That makes pre-existing shift UB in base/std.h
# abort the binary on every run, masking the real bug crashes we need to
# locate, and fails libafl's stricter build outright. Strip it so
# UBSAN_OPTIONS=halt_on_error=0 can take effect.
find . -name Makefile -exec sed -i 's/-fno-sanitize-recover=[^ ]*//g' {} +

# ghostpdl's autogen also injects a per-check UBSAN list into every
# Makefile compile rule, of the form:
#   -fsanitize=array-bounds,bool,builtin,enum,float-divide-by-zero,
#     function,integer-divide-by-zero,null,object-size,return,
#     returns-nonnull-attribute,shift,signed-integer-overflow,
#     unreachable,vla-bound,vptr
# (NOT the umbrella -fsanitize=undefined form, so matching "undefined"
# does nothing.)  UBSAN then fires "member access within null pointer"
# in base/gsalloc.c, psi/interp.c, psi/igcstr.c, base/std.h on every
# input. afl++ pins ASAN_OPTIONS=abort_on_error=1 at runtime, which
# turns each UBSAN report into SIGABRT, killing every seed during
# calibration. The transplanted bugs only need ASAN (all are
# heap/stack/UAF memory errors), so strip the UBSAN per-check list.
# The leading `-fsanitize=address` stays, so ASAN instrumentation is
# unaffected.
find . -name Makefile -exec sed -i 's/-fsanitize=array-bounds[^ ]*//g' {} +
# Safety net for the umbrella form in case any future check uses it.
find . -name Makefile -exec sed -i 's/-fsanitize=undefined//g' {} +

make -j$(nproc) libgs

$CC $CFLAGS -fno-zero-initialized-in-bss -c __bug_dispatch.c -o __bug_dispatch.o

$CXX $CXXFLAGS $CUPS_LDFLAGS -std=c++11 -I. \
    $SRC/gstoraster_fuzzer.cc \
    __bug_dispatch.o \
    -o "$OUT/gstoraster_fuzzer" \
    -Wl,-rpath='$ORIGIN' \
    $CUPS_LIBS \
    $LIB_FUZZING_ENGINE bin/gs.a

mkdir -p "$WORK/seeds"
for f in examples/*.{ps,pdf}; do
  s=$(sha1sum "$f" | awk '{print $1}')
  cp "$f" "$WORK/seeds/$s"
done
zip -j "$OUT/gstoraster_fuzzer_seed_corpus.zip" "$WORK"/seeds/*


# --- Seed corpus: expand original seeds and per-bug testcase candidates ---
# FuzzBench uses $OUT/{fuzz_target}_seed_corpus.zip as initial corpus.
# Create one seed variant for the default path plus one for each dispatch bit.
# Per-bug reproducers are used only as source material: exact crashing inputs
# are filtered out before packaging.
seed_zip="$OUT/gstoraster_fuzzer_seed_corpus.zip"
seed_target="$OUT/gstoraster_fuzzer"
mkdir -p /tmp/seeds_dispatch /tmp/original_seeds /tmp/benchmark_seed_candidates

if [ -f "$seed_zip" ]; then
    unzip -q -o "$seed_zip" -d /tmp/original_seeds 2>/dev/null || true
    for f in /tmp/original_seeds/*; do
        [ -f "$f" ] || continue
        base=$(basename "$f")
        for dispatch in '\x00\x00\x00' '\x01\x00\x00' '\x02\x00\x00' '\x04\x00\x00' '\x08\x00\x00' '\x10\x00\x00' '\x20\x00\x00' '\x40\x00\x00' '\x80\x00\x00' '\x00\x01\x00' '\x00\x02\x00' '\x00\x04\x00' '\x00\x08\x00' '\x00\x10\x00' '\x00\x20\x00' '\x00\x40\x00' '\x00\x80\x00' '\x00\x00\x01' '\x00\x00\x02' '\x00\x00\x04' '\x00\x00\x08' '\x00\x00\x10' '\x00\x00\x20' '\x00\x00\x40' '\x00\x00\x80'; do
            dispatch_name=$(printf '%s' "$dispatch" | tr -d '\x')
            printf '%b' "$dispatch" | cat - "$f" > "/tmp/seeds_dispatch/${base}.dispatch_${dispatch_name}"
        done
    done
fi

if [ -d /src/benchmark_seeds ]; then
    for f in /src/benchmark_seeds/*; do
        [ -f "$f" ] || continue
        base=$(basename "$f")
        size=$(wc -c < "$f")
        [ "$size" -gt 0 ] || continue

        cp "$f" "/tmp/benchmark_seed_candidates/${base}.exact"
        # Zero the dispatch byte (byte 0): deactivates dispatch-gated patches
        # while keeping the full APDU conversation and card driver routing intact.
        cp "$f" "/tmp/benchmark_seed_candidates/${base}.dispatch_zero"
        printf '\000' | dd of="/tmp/benchmark_seed_candidates/${base}.dispatch_zero" bs=1 seek=0 conv=notrunc 2>/dev/null || true
        for keep in 1 2 8 16 64 256 1024; do
            if [ "$size" -gt "$keep" ]; then
                head -c "$keep" "$f" > "/tmp/benchmark_seed_candidates/${base}.head_${keep}"
            fi
        done
        if [ "$size" -gt 1 ]; then
            head -c "$((size - 1))" "$f" > "/tmp/benchmark_seed_candidates/${base}.trim_1"
            cp "$f" "/tmp/benchmark_seed_candidates/${base}.zero_last"
            printf '\000' | dd of="/tmp/benchmark_seed_candidates/${base}.zero_last" bs=1 seek="$((size - 1))" conv=notrunc 2>/dev/null || true
            cp "$f" "/tmp/benchmark_seed_candidates/${base}.ff_last"
            printf '\377' | dd of="/tmp/benchmark_seed_candidates/${base}.ff_last" bs=1 seek="$((size - 1))" conv=notrunc 2>/dev/null || true
        fi
        if [ "$size" -gt 4 ]; then
            mid=$((size / 2))
            cp "$f" "/tmp/benchmark_seed_candidates/${base}.zero_mid"
            printf '\000' | dd of="/tmp/benchmark_seed_candidates/${base}.zero_mid" bs=1 seek="$mid" conv=notrunc 2>/dev/null || true
            cp "$f" "/tmp/benchmark_seed_candidates/${base}.ff_mid"
            printf '\377' | dd of="/tmp/benchmark_seed_candidates/${base}.ff_mid" bs=1 seek="$mid" conv=notrunc 2>/dev/null || true
        fi
    done
fi

if [ -x "$seed_target" ] && ls /tmp/benchmark_seed_candidates/* 1>/dev/null 2>&1; then
    for f in /tmp/benchmark_seed_candidates/*; do
        [ -f "$f" ] || continue
        if timeout 10s env ASAN_OPTIONS="${ASAN_OPTIONS:-detect_leaks=0:detect_stack_use_after_return=1}" "$seed_target" "$f" >/tmp/seed_replay.log 2>&1; then
            cp "$f" "/tmp/seeds_dispatch/poc_$(basename "$f")"
        fi
    done
fi

# Inject the filtered public ClusterFuzz corpus (already dispatch-zero prefixed
# and crash-filtered against this benchmark) as initial seeds.
for _z in /src/corpus_seeds*.zip; do
    [ -f "$_z" ] || continue
    echo "Unpacking initial corpus: $_z"
    unzip -q -o "$_z" -d /tmp/seeds_dispatch
done

# NOTE: do not use `ls /tmp/seeds_dispatch/*` here. With a large corpus the
# glob exceeds ARG_MAX (ndpi_reader: 35k seeds ~= 2.06MB > 2MB limit), the
# test silently fails, the seed zip is never written, and FuzzBench starts
# the fuzzers from a 2-byte fake seed. `find -quit` has no such limit.
if [ -n "$(find /tmp/seeds_dispatch -maxdepth 1 -type f -print -quit 2>/dev/null)" ]; then
    rm -f "$seed_zip"
    find /tmp/seeds_dispatch -maxdepth 1 -type f -print0 | xargs -0 zip -j -q "$seed_zip"
fi
